import json,pathlib,unicodedata
R=pathlib.Path(__file__).parent
P=json.load(open('data/data.json'));U='https://www.unicode.org/Public/17.0.0/ucd/UnicodeData.txt';L='https://www.loc.gov/catdir/cpso/romanization/'
F=[]
def add(cp,proposed,category,reason,sources):
 c=chr(cp);F.append(dict(codepoint=f'U+{cp:04X}',char=c,name=unicodedata.name(c,''),current=P[str(cp//256)][cp%256],proposed=proposed,category=category,reason=reason,sources=sources,claude_review='pending_parent'))
add(0xDD,'Y','wrong_letter','Acute accent on Latin Y; lowercase ý maps y and canonical decomposition is Y + acute.',[U])
add(0x1F2,'Dz','dropped_letter','Titlecase DZ digraph decomposes to D z; mapping drops z.',[U])
add(0x2B0,'h','wrong_letter','Modifier small h has compatibility decomposition h, not k.',[U])
add(0x3F2,'s','wrong_letter','Lunate sigma is sigma, not Latin c; ALA-LC explicitly maps ϲ to s.',[U,L+'greek.pdf'])
add(0x400,'E (Je if choosing a je convention)','wrong_vowel','This is Е with grave, not Ё/IO; Jo substitutes an o vowel. Ordinary Е maps E. Lowercase ѐ maps je, so case pair also disagrees.',[U])
add(0x98C,'L','wrong_vowel','Bengali VOCALIC L belongs to vocalic l series, not vocalic RR; dependent counterpart U+09E2 maps L.',[U])
add(0x9F1,'w (or v)','wrong_letter','Despite misleading Unicode formal name RA WITH LOWER DIAGONAL, Unicode identifies this as Assamese wa; r` is the wrong consonant.', ['https://www.unicode.org/versions/Unicode16.0.0/UnicodeStandard-16.0.pdf',L+'assamese.pdf'])
add(0xA2D,'bh','wrong_letter','Gurmukhi BHA is bha in ALA-LC, consonantal skeleton bh; bb is not the corresponding consonant.',[L+'panjabi.pdf',U])
add(0xE0B,'s','wrong_letter','Thai SO SO is s initially, t finally; ch is not either reading.',[L+'thai.pdf',U])
add(0xE45,'vowel-length operation (fallback aa)','wrong_vowel','Lakkhangyao lengthens ฤ or ฦ; ao introduces an unrelated o. Unicode calls it a vowel length sign; a correct readable result requires context.', ['https://www.unicode.org/charts/PDF/U0E00.pdf',L+'thai.pdf'])
add(0xE95,'t','wrong_letter','Lao TO is t, not h; ALA-LC uses t both initially and finally.',[L+'lao.pdf'])
add(0xEAE,'h','dropped_letter','Lao HO TAM is h initially. Empty string erases an ordinary consonant.',[L+'lao.pdf'])
add(0x698,'zh','wrong_letter','Persian/Pashto JEH is zh, not j; distinct from Arabic JEEM which maps j.',[L+'persian.pdf',L+'pushto.pdf'])
add(0x6A9,'k','wrong_letter','Persian/Urdu keheh is k, not kh; LoC Persian note 2 explicitly shows ک as kaf form.',[L+'persian.pdf'])
add(0x6D0,'e','dropped_vowel','Pashto vowel E is romanized e. Empty string deletes a written vowel.',[L+'pushto.pdf',U])
add(0x685,'ts or s (ALA-LC ṡ)','wrong_letter','Pashto letter TSE is represented by ALA-LC ṡ; ts/s depend on dialect. H is not either consonant.',[L+'pushto.pdf'])
add(0x6AB,'g','wrong_letter','Pashto ګ is g in the ALA-LC alphabet; the data uses K.',[L+'pushto.pdf'])
add(0x5F2,'ey (ay in applicable words)','wrong_vowel','Yiddish double yod represents ey/ay, not i; LoC explicitly lists both diphthongs. Prefer ey as unpointed YIVO default, with ay requiring context/pointing.',[L+'hebrew.pdf'])
add(0x390,'i','case_error','Lowercase Greek iota with dialytika and tonos is currently uppercase I, while other lowercase iotas map i.',[U])
add(0x478,'U','case_error','Capital Cyrillic UK maps lowercase u, while lowercase U+0479 also maps u; restore the capital U.',[U])
add(0x4D0,'A','case_error','Capital Cyrillic A with breve maps lowercase a; lowercase U+04D1 maps a.',[U])
add(0x38E,'Y (modern/default) or consistent scheme','scheme_inconsistency','Capital upsilon with tonos uses U while unaccented Υ and lowercase ύ use Y/y. U can occur in classical romanization, so this is scheme/case consistency, not universally an impossible reading.',[U,L+'greek.pdf'])
add(0x1B1,'U','scheme_inconsistency','Latin capital upsilon maps Y although its lowercase ʊ maps U (SAMPA-style). Unlike Greek upsilon, this is a Latin IPA/orthographic letter. Needs policy review.',[U])
add(0xABF if False else 0xAAF,'y before vowel signs','context_or_scheme','Gujarati YA uniquely includes inherent a (ya), while neighboring consonants are bare and dependent vowels append, producing duplicate/inappropriate a before explicit vowel signs. Isolated ya itself is a valid romanization.',[U,L+'gujarati.pdf'])
add(0xA71,'double following consonant','context_error','Gurmukhi addak/adhik marks gemination; fixed H inserts unrelated h. ALA-LC specifies doubling the following consonant.',[L+'panjabi.pdf'])
add(0x651,'double preceding consonant','context_error','Arabic shadda marks gemination; fixed W inserts unrelated w. ALA-LC Persian/Pashto specifies doubling the letter/digraph.',[L+'persian.pdf',L+'pushto.pdf'])
add(0xB35,'v (or w)','dropped_letter','Odia VA is a consonant, not an ignorable sign; data currently drops it. Primary Unicode identity supports nonempty consonantal fallback; preferred scheme needs specialist confirmation.',[U])
add(0x95C,'r/rr (ASCII of ṛ)','needs_scheme_confirmation','Devanagari DDDHA is the flap ṛ (ड़), not an aspirated dddh sequence. Existing data RRA uses rr. Hindi chart retrieval not yet verified; ask language reviewer.',[U])
(R/'findings.json').write_text(json.dumps(F,ensure_ascii=False,indent=2))
print(len(F),'findings saved')
